  "PROP-6a4369e9-inv-029": {
    "property_id": "PROP-6a4369e9-inv-029",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-029",
      "classification": "vulnerability",
      "code_path": "beacon_node/network/src/network_beacon_processor/rpc_methods.rs::handle_blobs_by_range_request_inner::L1063-1079",
      "proof_trace": "BlobsByRange serves ALL blobs in requested range without checking fork epoch. After Fulu activation, it continues serving post-Fulu blobs instead of restricting to pre-Fulu (Deneb/Electra) blobs only, violating the fork transition invariant that blob_sidecars_by_range is deprecated post-Fulu.",
      "attack_scenario": "Peer requests BlobsByRange for slots >= FULU_FORK_EPOCH. Node serves post-Fulu blobs via deprecated RPC method instead of rejecting or filtering, causing protocol confusion and potential consensus divergence with clients that correctly implement the fork transition.",
      "checklist_id": "PROP-6a4369e9-inv-029"
    },
    "text": "During transition, blob_sidecars_by_range must serve only pre-Fulu epoch blobs.",
    "assertion": "forall sidecar in transition_resp: compute_epoch(sidecar.slot) < FULU_FORK_EPOCH",
    "covers": "SG-011",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

